import { create } from 'zustand'

// ============================================================================
// Types
// ============================================================================

/** A part from the catalog, ready to be added to cart */
export interface PartCatalogItem {
  id: string
  barcode: string
  name: string
  priceNet: number // in cents (integer)
  quantityOnHand: number
}

/** VAT rate ID constants — matches server vatRates table */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

/** A single line item in the cart */
export interface CartLineItem {
  partId: string
  barcode: string
  name: string
  priceNet: number // ex-tax cents per unit (snapshot at add time)
  quantity: number
  vatRateId: keyof typeof VAT_RATES
  discountPercent: number | null // basis points, e.g. 1000 = 10%
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

/** Customer selector item from GET /customers (search response) */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

/** Payload sent to POST /sales for checkout */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
  }>
}

/** Success info returned from POST /sales */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

// ============================================================================
// Helpers — Line item math (all amounts in cents, integer)
// ============================================================================

/**
 * Compute line totals from quantity, unit price, discount, and VAT rate.
 *
 * Formula: discountedNetPerUnit = unitPriceNet × (1 - discountBps / 10000)
 *          lineNetTotal = discountedNetPerUnit × quantity
 *          lineVatTotal = round(lineNetTotal × vatRateBps / 10000)
 *          lineGrossTotal = lineNetTotal + lineVatTotal
 */
function computeLineTotals(
  priceNet: number,
  quantity: number,
  discountPercentBps: number | null,
  vatRateBps: number
): { net: number; vat: number; gross: number } {
  const discountFactor = discountPercentBps ? 1 - discountPercentBps / 10000 : 1
  const discountedNetPerUnit = Math.round(priceNet * discountFactor)
  const lineNetTotal = discountedNetPerUnit * quantity
  const lineVatTotal = Math.round(lineNetTotal * vatRateBps / 10000)

  return { net: lineNetTotal, vat: lineVatTotal, gross: lineNetTotal + lineVatTotal }
}

// ============================================================================
// Store
// ============================================================================

interface PosCartState {
  // Line items in the cart
  lineItems: CartLineItem[]

  // Selected customer (null = walk-in)
  customerId: string | null

  // Checkout state
  checkoutError: string | null
  checkoutSuccess: CheckoutSuccess | null
  isCheckingOut: boolean

  // Computed totals (derived from line items)
  subtotalNet: number
  vatTotal: number
  totalGross: number

  // Whether the cart can be checked out
  canCheckout: boolean
}

interface PosCartActions {
  // Line item operations
  addLineItem: (part: PartCatalogItem, quantity?: number) => void
  removeLineItem: (partId: string) => void
  updateQuantity: (partId: string, quantity: number) => void
  applyDiscount: (partId: string, discountPercentBps: number) => void
  changeVatRate: (partId: string, newVatRateId: keyof typeof VAT_RATES) => void

  // Customer selection
  setCustomer: (customerId: string | null) => void

  // Checkout state management
  clearCart: () => void
  clearErrors: () => void
  startCheckout: () => void
  finishCheckout: (success: CheckoutSuccess) => void
  failCheckout: (error: string) => void
  setCheckoutError: (error: string | null) => void
  setCheckoutSuccess: (success: CheckoutSuccess | null) => void

  // Get checkout payload for API call
  getCheckoutPayload: () => CheckoutPayload
}

export type PosCartStore = PosCartState & PosCartActions

const initialState: PosCartState = {
  lineItems: [],
  customerId: null,
  checkoutError: null,
  checkoutSuccess: null,
  isCheckingOut: false,
  subtotalNet: 0,
  vatTotal: 0,
  totalGross: 0,
  canCheckout: false,
}

function computeTotals(lineItems: CartLineItem[]): { subtotalNet: number; vatTotal: number; totalGross: number } {
  let subtotalNet = 0
  let vatTotal = 0

  for (const item of lineItems) {
    const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
    const totals = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
    subtotalNet += totals.net
    vatTotal += totals.vat
  }

  return { subtotalNet, vatTotal, totalGross: subtotalNet + vatTotal }
}

/** Compute line-level totals for a single cart item */
function computeItemTotals(item: {
  priceNet: number
  quantity: number
  discountPercent: number | null
  vatRateId: keyof typeof VAT_RATES
}): Pick<CartLineItem, 'lineTotalNet' | 'lineTotalVat' | 'lineTotalGross'> {
  const vatRateBps = VAT_RATES[item.vatRateId] ?? 2100
  const { net, vat, gross } = computeLineTotals(item.priceNet, item.quantity, item.discountPercent, vatRateBps)
  return { lineTotalNet: net, lineTotalVat: vat, lineTotalGross: gross }
}

function updateComputedState(state: PosCartStore): Partial<PosCartState> {
  const totals = computeTotals(state.lineItems)
  return {
    ...totals,
    canCheckout: state.lineItems.length > 0,
  }
}

export const useCartStore = create<PosCartStore>((set, get) => ({
  ...initialState,

  // ── Line Item Operations ────────────────────────────────────────

  addLineItem: (part, quantity = 1) => {
    set((state) => {
      // If quantity is 0 or less, remove existing line item
      if (quantity <= 0) {
        const newItems = state.lineItems.filter((item) => item.partId !== part.id)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      const existingIndex = state.lineItems.findIndex((item) => item.partId === part.id)

      let newItems: CartLineItem[]

      if (existingIndex >= 0) {
        // Increment quantity for existing line item
        const existingItem = state.lineItems[existingIndex]
        const newQty = existingItem.quantity + quantity
        newItems = [...state.lineItems]
        newItems[existingIndex] = {
          ...existingItem,
          quantity: newQty,
          ...computeItemTotals({ priceNet: existingItem.priceNet, quantity: newQty, discountPercent: existingItem.discountPercent, vatRateId: existingItem.vatRateId }),
        }
      } else {
        // Add new line item
        const totals = computeItemTotals({ priceNet: part.priceNet, quantity, discountPercent: null, vatRateId: DEFAULT_VAT_RATE })
        const newItem: CartLineItem = {
          partId: part.id,
          barcode: part.barcode,
          name: part.name,
          priceNet: part.priceNet,
          quantity,
          vatRateId: DEFAULT_VAT_RATE,
          discountPercent: null,
          ...totals,
        }
        newItems = [...state.lineItems, newItem]
      }

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  removeLineItem: (partId) => {
    set((state) => {
      const newItems = state.lineItems.filter((item) => item.partId !== partId)
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  updateQuantity: (partId, quantity) => {
    set((state) => {
      // Remove if quantity is exactly 0
      if (quantity === 0) {
        const newItems = state.lineItems.filter((item) => item.partId !== partId)
        return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
      }

      // Clamp to minimum of 1 (negative values become 1)
      const clampedQty = Math.max(1, quantity)

      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, quantity: clampedQty, ...computeItemTotals({ ...item, quantity: clampedQty }) }
          : item
      )

      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  applyDiscount: (partId, discountPercentBps) => {
    set((state) => {
      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, discountPercent: discountPercentBps, ...computeItemTotals({ ...item, discountPercent: discountPercentBps }) }
          : item
      )
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  changeVatRate: (partId, newVatRateId) => {
    set((state) => {
      const newItems = state.lineItems.map((item) =>
        item.partId === partId
          ? { ...item, vatRateId: newVatRateId, ...computeItemTotals({ ...item, vatRateId: newVatRateId }) }
          : item
      )
      return { lineItems: newItems, ...updateComputedState({ ...state, lineItems: newItems }) }
    })
  },

  // ── Customer Selection ──────────────────────────────────────────

  setCustomer: (customerId) => {
    set({ customerId })
  },

  // ── Checkout State Management ───────────────────────────────────

  clearCart: () => {
    set({ ...initialState, lineItems: [], customerId: null })
  },

  clearErrors: () => {
    set({ checkoutError: null, checkoutSuccess: null })
  },

  startCheckout: () => {
    set({ isCheckingOut: true, checkoutError: null })
  },

  failCheckout: (error) => {
    set({ isCheckingOut: false, checkoutError: error })
  },

  setCheckoutError: (error) => {
    set({ checkoutError: error })
  },

  setCheckoutSuccess: (success) => {
    set({ checkoutSuccess: success })
  },

  finishCheckout: (success) => {
    set({
      isCheckingOut: false,
      checkoutSuccess: success,
      lineItems: [],
      customerId: null,
      subtotalNet: 0,
      vatTotal: 0,
      totalGross: 0,
      canCheckout: false,
    })
  },

  // ── Checkout Payload Builder ────────────────────────────────────

  getCheckoutPayload: (): CheckoutPayload => {
    const state = get()
    return {
      customerId: state.customerId,
      paymentMethod: 'cash', // default — can be overridden by caller
      lineItems: state.lineItems.map((item) => ({
        partId: item.partId,
        quantity: item.quantity,
        unitPriceNet: item.priceNet,
        vatRateId: item.vatRateId,
        description: item.name,
      })),
    }
  },
}))

/**
 * POS feature types — explicit interfaces using shared domain types.
 *
 * This module defines all types used by the POS feature, importing from
 * `shared/types/` as the single source of truth for domain entities.
 */

import type { Product } from '@shared/types/product.js'
import type { Customer } from '@shared/types/customer.js'

// ============================================================================
// Shared Type Aliases — derived from shared types
// ============================================================================

/** Compact catalog item for list/table display and cart operations. */
export interface PartCatalogItem extends Pick<Product, 'id' | 'barcode' | 'name' | 'priceNet' | 'quantityOnHand'> {}

/** Customer selector item for dropdown selectors (compact shape). */
export interface CustomerSelectorItem extends Pick<Customer, 'id' | 'type'> {
  /** Human-readable name: "firstName lastName" for private, companyName for company. */
  displayName: string
}

// ============================================================================
// Cart Types — internal to the POS feature
// ============================================================================

/** VAT rate ID constants — matches server vatRates table. */
export const VAT_RATES = {
  'vat-standard': 2100, // 21%
  'vat-reduced': 600,   // 6%
  'vat-zero': 0,        // 0%
} as const

/** Default VAT rate for parts. */
export const DEFAULT_VAT_RATE = 'vat-standard' as const

/** A single line item in the cart (with computed totals). */
export interface CartLineItem {
  partId: string
  barcode: string
  name: string
  priceNet: number // ex-tax cents per unit (snapshot at add time)
  quantity: number
  vatRateId: keyof typeof VAT_RATES
  discountPercent: number | null // basis points, e.g. 1000 = 10%
  // Computed totals (updated whenever qty/discount changes)
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
}

// ============================================================================
// Checkout Types — request/response shapes for the checkout flow
// ============================================================================

/** Payload sent to POST /sales for checkout. */
export interface CheckoutPayload {
  customerId: string | null
  paymentMethod: 'cash' | 'card'
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
  }>
}

/** Success info returned from POST /sales. */
export interface CheckoutSuccess {
  saleNumber: string
  totalGross: number
}

/**
 * Combobox — A generic searchable dropdown built on Radix Popover.
 *
 * Provides:
 * - Search input with debounce (managed by caller via `onSearchChange`)
 * - Floating results list with keyboard navigation
 * - Loading and empty states
 * - Selected item display with optional clear button
 *
 * Usage:
 * ```tsx
 * <Combobox<PostalCodeResult>
 *   items={results}
 *   isLoading={isLoading}
 *   value={selectedItem}
 *   onValueChange={(item) => setSelected(item)}
 *   onSearchChange={(query) => setSearch(query)}
 *   placeholder="Search..."
 *   renderOption={(item) => <span>{item.name}</span>}
 * />
 * ```
 */

import { useState, useRef, useEffect, useCallback } from 'react'
import { cn } from '@/shared/lib/utils.js'
import { X, Loader2 } from 'lucide-react'
import type { ComponentPropsWithoutRef, KeyboardEvent as ReactKeyboardEvent } from 'react'

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

export interface ComboboxProps<T> extends Omit<ComponentPropsWithoutRef<'div'>, 'onValueChange'> {
  /** Available items to display in the dropdown. */
  items: T[]
  /** Whether a search is currently in progress. */
  isLoading: boolean
  /** Currently selected item (null = unselected). */
  value: T | null
  /** Called when user selects an item. Pass null to clear selection. */
  onValueChange: (value: T | null) => void
  /** Called with the current search query string as user types. */
  onSearchChange: (query: string) => void
  /** Placeholder text for the input field. */
  placeholder?: string
  /** Render function for each dropdown item. Receives the full item object. */
  renderOption: (item: T, index: number) => React.ReactNode
  /** Whether the combobox is disabled. Shows a read-only label when true and has a value. */
  disabled?: boolean
}

// ---------------------------------------------------------------------------
// Component — Combobox
// ---------------------------------------------------------------------------

export function Combobox<T extends { [key: string]: unknown }>({
  items,
  isLoading,
  value,
  onValueChange,
  onSearchChange,
  placeholder = 'Search...',
  renderOption,
  disabled = false,
  className,
}: ComboboxProps<T>) {
  const [isOpen, setIsOpen] = useState(false)
  const [highlightedIndex, setHighlightedIndex] = useState(-1)

  // Local search query state — drives the input value directly.
  // onSearchChange is called as a side-effect for parent integration.
  const [searchQuery, setSearchQuery] = useState('')

  // Local controlled input — synced with value state.
  // When a selection is made, the display shows it and the input area becomes read-only.
  // When cleared, we reset to search mode.
  const [displayValue, setDisplayValue] = useState<string>('')

  // Keep displayValue in sync with external value prop.
  useEffect(() => {
    if (value) {
      setDisplayValue(String(value.name))
    } else {
      setDisplayValue('')
    }
  }, [value])

  // Refs for focus management and click-outside detection.
  const containerRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const listRef = useRef<HTMLUListElement>(null)

  // Reset highlight when items change (new search results).
  useEffect(() => {
    setHighlightedIndex(-1)
  }, [items])

  /** Close the dropdown. */
  const close = useCallback(() => {
    setIsOpen(false)
    setHighlightedIndex(-1)
  }, [])

  /** Open the dropdown and focus the input. */
  const open = useCallback(() => {
    if (!disabled) {
      setIsOpen(true)
      // If we have a value, select it all so user can type over immediately.
      setTimeout(() => {
        inputRef.current?.focus()
        if (displayValue && isOpen) {
          inputRef.current?.select()
        }
      }, 0)
    }
  }, [disabled, displayValue, isOpen])

  /** Handle selecting an item. */
  const handleSelect = useCallback((item: T) => {
    onValueChange(item)
    close()
  }, [onValueChange, close])

  /** Clear selection and reopen for a new search. */
  const handleClear = useCallback((e: React.MouseEvent) => {
    e.stopPropagation()
    setSearchQuery('')
    onValueChange(null)
    close()
    // Reopen so user can immediately type again.
    setTimeout(() => inputRef.current?.focus(), 0)
  }, [onValueChange, close])

  /** Handle keyboard navigation in the dropdown. */
  const handleKeyDown = useCallback((e: ReactKeyboardEvent<HTMLInputElement>) => {
    if (!isOpen) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightedIndex((prev) => Math.min(prev + 1, items.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightedIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter': {
        e.preventDefault()
        if (highlightedIndex >= 0 && highlightedIndex < items.length) {
          handleSelect(items[highlightedIndex])
        } else if (!value && items.length > 0) {
          // Select first item when nothing is selected and there are results.
          handleSelect(items[0])
        }
        break
      }

      case 'Escape':
        e.preventDefault()
        close()
        break

      default:
        break
    }
  }, [isOpen, highlightedIndex, items.length, value, handleSelect, close])

  /** Handle input blur — close dropdown if focus leaves the container. */
  const handleBlur = useCallback((e: React.FocusEvent<HTMLInputElement>) => {
    // Check if focus is moving to a descendant (the results list).
    const relatedTarget = e.relatedTarget as HTMLElement | null
    if (relatedTarget?.closest('[data-combobox-list]')) return
    close()
  }, [close])

  // Scroll highlighted item into view.
  useEffect(() => {
    if (highlightedIndex >= 0 && listRef.current) {
      const el = listRef.current.children[highlightedIndex] as HTMLElement | null
      el?.scrollIntoView({ block: 'nearest' })
    }
  }, [highlightedIndex])

  // -----------------------------------------------------------------------
  // Render — selected display (when not editing) or input (when open/searching)
  // -----------------------------------------------------------------------

  const hasValue = value !== null && displayValue.length > 0

  if (disabled && hasValue) {
    return (
      <div className={cn('text-sm text-muted-foreground', className)}>
        {displayValue}
      </div>
    )
  }

  return (
    <div ref={containerRef} className={cn(className)}>
      {/* Input wrapper */}
      <div
        role="combobox"
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        onClick={open}
        className={cn(
          'flex h-10 w-full items-center gap-2 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-within:outline-none focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2 cursor-text',
        )}
      >
        {/* Selected value display or search input */}
        {hasValue ? (
          <div className="flex flex-1 items-center gap-1.5">
            <span>{displayValue}</span>
            {!disabled && (
              <button
                type="button"
                onClick={handleClear}
                className="ml-auto p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                tabIndex={-1}
              >
                <X className="h-3 w-3" />
                <span className="sr-only">Clear selection</span>
              </button>
            )}
          </div>
        ) : (
          <input
            ref={inputRef}
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              onSearchChange(e.target.value)
            }}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            placeholder={placeholder}
            className="flex-1 bg-transparent outline-none text-sm placeholder:text-muted-foreground disabled:cursor-not-allowed"
            disabled={disabled}
          />
        )}

        {/* Loading indicator */}
        {isLoading && (
          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground shrink-0" />
        )}
      </div>

      {/* Dropdown results */}
      {isOpen && !disabled && (
        <ul
          ref={listRef}
          data-combobox-list
          role="listbox"
          className="absolute z-50 mt-1 max-h-64 w-full overflow-y-auto rounded-md border bg-popover text-popover-foreground shadow-lg outline-none"
        >
          {isLoading && items.length === 0 ? (
            <li className="flex items-center gap-2 px-3 py-2 text-sm text-muted-foreground">
              <Loader2 className="h-4 w-4 animate-spin" />
              Searching...
            </li>
          ) : items.length === 0 ? (
            <li className="px-3 py-2 text-sm text-muted-foreground">No results</li>
          ) : (
            items.map((item, index) => (
              <li
                key={String(item.code ?? item.name)} // Use unique identifier if available.
                role="option"
                aria-selected={index === highlightedIndex}
                onMouseDown={(e) => {
                  e.preventDefault() // Prevent focus from leaving input (which triggers blur/close before React processes click)
                  handleSelect(item)
                }}
                className={cn(
                  'px-3 py-2 text-sm cursor-pointer transition-colors',
                  index === highlightedIndex && 'bg-accent text-accent-foreground'
                )}
              >
                {renderOption(item, index)}
              </li>
            ))
          )}
        </ul>
      )}
    </div>
  )
}

import { useCallback, useState } from 'react'
import type { PaymentMethod as PaymentMethodType } from '@shared/validations'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { useCartStore } from '../store'
import { PartsSearch } from '../components/PartsSearch'
import { CartDisplay } from '../components/CartDisplay'
import { CustomerSelector } from '../components/CustomerSelector'
import { PaymentDialog } from '../components/PaymentDialog'
import { submitCheckout, parseCheckoutSuccess } from '../services/checkout'

// ============================================================================
// Component — POS Page (split-panel layout)
// ============================================================================

export function PosPage() {
  const startCheckout = useCartStore((s) => s.startCheckout)
  const finishCheckout = useCartStore((s) => s.finishCheckout)
  const failCheckout = useCartStore((s) => s.failCheckout)
  const getCheckoutPayload = useCartStore((s) => s.getCheckoutPayload)

  // Handle checkout submission
  const handleCheckout = useCallback(
    async (method: PaymentMethodType) => {
      startCheckout()

      try {
        const payload = getCheckoutPayload()
        // Override payment method from the form selection
        const checkoutPayload = { ...payload, paymentMethod: method }

        const response = await submitCheckout(checkoutPayload)
        const success = parseCheckoutSuccess(response)
        finishCheckout(success)
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error during checkout'
        failCheckout(message)
      }
    },
    [startCheckout, finishCheckout, failCheckout, getCheckoutPayload]
  )

  const [paymentOpen, setPaymentOpen] = useState(false)
  const canCheckout = useCartStore((s) => s.canCheckout)

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <CardTitle className="text-xl">Point of Sale</CardTitle>
      </CardHeader>

      {/* Split-panel layout */}
      <div className="flex flex-1 gap-4 px-6 pb-4 overflow-hidden">
        {/* Left panel — Parts search + Cart display */}
        <div className="flex-1 flex flex-col gap-4 min-w-0">
          <Card>
            <CardHeader className="pb-2 px-4 pt-4">
              <CardTitle className="text-base">Add Items</CardTitle>
            </CardHeader>
            <CardContent className="px-4 pb-4">
              <PartsSearch />
            </CardContent>
          </Card>

          <div className="flex-1 min-h-0">
            <CartDisplay />
          </div>
        </div>

        {/* Right panel — Customer selector + Pay button */}
        <div className="w-80 shrink-0 flex flex-col gap-4 overflow-y-auto">
          <CustomerSelector />
          <Button
            onClick={() => setPaymentOpen(true)}
            disabled={!canCheckout}
            size="lg"
            className="w-full"
          >
            Pay
          </Button>
        </div>
      </div>

      {/* Payment dialog */}
      <PaymentDialog
        open={paymentOpen}
        onClose={() => setPaymentOpen(false)}
        onCheckout={handleCheckout}
      />
    </div>
  )
}

